theme.css:
/* theme: Senate Seal | A single red seal on a plain institutional page marks the day's subpoenas, flips, and market tremors. */
/* mood: neutral */
/* layout: hero=poster; major-events=timeline/stack; political-news=numbered/grid-2; financial-news=stat/grid-2; tech-news=outline/grid-2; entertainment-news=plain/stack; sports=split/masonry; music-releases=plain/stack; stock-analysis=stat/grid-3; outlook=outline/stack */

.diary-page {
  --paper: #f4f4f4;
  --paper-alt: #e8e8e8;
  --ink: #1a1a1a;
  --ink-soft: #2e2e2e;
  --muted: #4d4d4d;
  --accent: #1a1a1a;
  --accent-ink: #ffffff;
  --rule: #c9c9c9;
  --font-display: var(--ff-instrument), Georgia, serif;
  --font-body: var(--ff-newsreader), Georgia, serif;
  --font-ui: var(--ff-inter), system-ui, sans-serif;
}

.diary-page[data-hero="poster"] .diary-hero {
  background: var(--ink);
  border-bottom: 4px solid var(--paper-alt);
  position: relative;
}

.diary-page[data-hero="poster"] .diary-hero::before {
  content: "SENATE";
  position: absolute;
  top: 1rem;
  right: 2rem;
  font-family: var(--font-display);
  font-size: 1.4rem;
  letter-spacing: 0.35em;
  color: var(--accent-ink);
  opacity: 0.55;
  writing-mode: vertical-rl;
}

.diary-page[data-hero="poster"] .diary-hero-inner {
  padding-block: 2.5rem 3.5rem;
  max-width: 60rem;
}

.diary-page[data-hero="poster"] .diary-crumbs a {
  color: var(--accent-ink);
}

.diary-page[data-hero="poster"] .diary-crumbs a:hover {
  color: var(--accent-ink);
  opacity: 0.8;
}

.diary-page[data-hero="poster"] .diary-kicker {
  color: var(--accent-ink);
  font-weight: 700;
  letter-spacing: 0.22em;
  opacity: 0.9;
}

.diary-page[data-hero="poster"] .diary-title {
  color: var(--accent-ink);
  font-family: var(--font-display);
  font-size: clamp(3rem, 9vw, 6rem);
  font-weight: 400;
  line-height: 0.95;
  letter-spacing: -0.01em;
  text-transform: none;
  max-width: 12ch;
  margin-inline: auto;
  text-align: center;
}

.diary-page[data-hero="poster"] .diary-summary {
  color: var(--accent-ink);
  max-width: 34rem;
  margin-inline: auto;
  text-align: center;
  font-size: clamp(1.1rem, 1.8vw, 1.3rem);
  line-height: 1.6;
  margin-top: 1.25rem;
  opacity: 0.95;
}

.diary-page[data-hero="poster"] .diary-theme-note {
  color: var(--accent-ink);
  max-width: 34rem;
  margin-inline: auto;
  text-align: center;
  opacity: 0.85;
}

.diary-page[data-hero="poster"] .diary-theme-name {
  background: var(--accent-ink);
  color: var(--ink);
  font-family: var(--font-ui);
  font-size: 0.78rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.diary-page .diary-hero-inner {
  position: relative;
}

.diary-page .diary-hero-inner::after {
  content: "— 56 —";
  position: absolute;
  bottom: 0.75rem;
  left: 50%;
  transform: translateX(-50%);
  font-family: var(--font-display);
  font-size: 2.2rem;
  color: var(--accent-ink);
  opacity: 0.35;
  letter-spacing: 0.1em;
}

.diary-page .diary-body {
  padding-top: 2rem;
}

.diary-page .diary-toc {
  background: var(--paper);
}

.diary-page .diary-toc-label {
  color: var(--muted);
}

.diary-page .diary-toc-link,
.diary-page .diary-toc-top,
.diary-page .diary-toc-bottom {
  color: var(--muted);
}

.diary-page .diary-toc-link:hover,
.diary-page .diary-toc-top:hover,
.diary-page .diary-toc-bottom:hover,
.diary-page .diary-toc-link.is-active {
  color: var(--ink);
}

.diary-page .diary-toc-number {
  color: var(--ink);
}

.diary-page .diary-section {
  border-top: 1px solid var(--rule);
  position: relative;
}

.diary-page .diary-section-head {
  border-bottom: 2px solid var(--ink);
  padding-bottom: 0.75rem;
  margin-bottom: 2rem;
}

.diary-page .diary-section-number {
  color: var(--ink);
  font-family: var(--font-ui);
  font-weight: 700;
  font-size: 0.85rem;
}

.diary-page .diary-section-title {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: clamp(2rem, 4vw, 2.8rem);
  font-weight: 400;
  letter-spacing: -0.01em;
}

.diary-page .diary-prose {
  color: var(--ink-soft);
}

.diary-page .diary-prose a {
  color: var(--ink);
}

.diary-page .diary-prose strong {
  color: var(--ink);
}

.diary-page .diary-prose blockquote {
  border-left-color: var(--ink);
  color: var(--ink);
}

.diary-page .diary-card-thread {
  border-color: var(--ink);
  color: var(--ink);
}

.diary-page .diary-card-thread:hover {
  background: var(--ink);
  color: var(--accent-ink);
}

.diary-page .diary-card--timeline .diary-card-inner {
  padding-left: 2rem;
}

.diary-page .diary-card--timeline .diary-card-inner::before {
  left: 0.4rem;
  width: 2px;
  background: var(--rule);
}

.diary-page .diary-card--timeline .diary-card-inner::after {
  left: 0;
  width: 0.85rem;
  height: 0.85rem;
  background: var(--ink);
  box-shadow: 0 0 0 4px var(--paper);
}

.diary-page .diary-card--numbered .diary-card-index {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 3.5rem;
  font-weight: 400;
}

.diary-page .diary-card--numbered .diary-card-inner {
  grid-template-columns: auto minmax(0, 1fr);
  column-gap: 1.5rem;
  border-bottom: 1px solid var(--rule);
  padding-bottom: 1.25rem;
}

.diary-page .diary-card--outline .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  background: var(--paper);
  box-shadow: 0 2px 8px rgb(0 0 0 / 0.04);
  padding: 1.5rem;
  position: relative;
}

.diary-page .diary-card--outline .diary-card-inner::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 4px;
  height: 100%;
  background: var(--ink);
}

.diary-page .diary-card--stat .diary-card-inner {
  border-top: 4px solid var(--ink);
  background: var(--paper-alt);
  padding: 1.25rem;
}

.diary-page .diary-card-figure {
  color: var(--ink);
  font-family: var(--font-display);
  font-size: clamp(2.5rem, 10cqi, 3.75rem);
  font-weight: 400;
}

.diary-page .diary-card--split .diary-card-inner {
  border-top: 2px solid var(--ink);
}

.diary-page .diary-card--tile .diary-card-inner {
  background: var(--paper-alt);
  border-radius: 0;
}

.diary-page .diary-card--plain .diary-card-body {
  font-size: 1.15rem;
}

.diary-page .diary-stories--grid-2 {
  gap: 2rem;
}

.diary-page .diary-stories--grid-3 {
  gap: 2rem;
}

.diary-page .diary-stories--stack {
  gap: 2.5rem;
}

.diary-page .diary-stories--masonry {
  column-gap: 2rem;
}

.diary-page .diary-stories--masonry > .diary-card {
  margin-bottom: 2rem;
}

.diary-page .diary-markets-label {
  color: var(--muted);
}

.diary-page .diary-spark {
  background: var(--paper-alt);
  border: 1px solid var(--rule);
  border-radius: 0;
}

.diary-page .diary-spark-label {
  color: var(--muted);
}

.diary-page .diary-spark-value {
  color: var(--ink);
}

.diary-page .diary-spark.is-up .diary-spark-change {
  color: var(--ink);
}

.diary-page .diary-spark.is-down .diary-spark-change {
  color: var(--ink);
}

.diary-page .diary-spark .diary-spark-line {
  stroke: var(--ink-soft);
}

.diary-page .diary-footer {
  border-top: 2px solid var(--ink);
}

.diary-page .diary-footer a {
  color: var(--ink);
}

.diary-page .diary-footer a:hover {
  color: var(--ink);
  opacity: 0.7;
}

.diary-page .diary-card-title {
  font-family: var(--font-display);
  font-size: 1.6rem;
  font-weight: 400;
  line-height: 1.15;
  letter-spacing: -0.01em;
  color: var(--ink);
}

.diary-page .diary-card-lede {
  border-left: 3px solid var(--ink);
  color: var(--ink);
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 400;
  line-height: 1.5;
}

.diary-page .diary-card--banner .diary-card-inner {
  border: 1px solid var(--rule);
  border-radius: 0;
  overflow: hidden;
}

.diary-page .diary-card--banner .diary-card-title {
  background: var(--ink);
  color: var(--accent-ink);
  font-family: var(--font-display);
  font-size: 1.3rem;
  font-weight: 400;
  padding: 0.85rem 1.25rem;
}

.diary-page .diary-card--banner .diary-card-body {
  padding: 1.25rem;
  background: var(--paper);
}

.diary-page .diary-card--banner .diary-card-thread {
  margin: 1rem 1.25rem 0;
}

.diary-page .diary-prose ul > li::before {
  background: var(--ink);
}

.diary-page .diary-prose ol > li::marker {
  color: var(--ink);
}

.diary-page .diary-prose pre {
  background: var(--paper-alt);
  border-color: var(--rule);
}

.diary-page .diary-card--timeline:last-child .diary-card-inner::before {
  bottom: 0;
}

@media (min-width: 1024px) {
  .diary-page .diary-toc {
    margin-top: 4rem;
  }
}
